(二) 程式撰寫 
 本作品電機控制部分使用Arduino UNO 板及電控感測元件，因考量需同時控制多項元件會有時間延遲及程式冗長不易撰寫的因素，故將兩傳動機構分開獨立撰寫個別控制程式，並使用兩塊Arduino Uno 板分別控制兩機構之作動，相關程式碼及註解內容詳述如下。 
(1) 導風板外推機構控制Arduino 程式碼 
//定義區 
#include <ezButton.h>// 載入ezButton.h 函式庫 
ezButton limitSwitch_1(A0); // create ezButton object that attach to pin A0; 極限開關1 插 pinA0 
ezButton limitSwitch_2(A1); // create ezButton object that attach to pin A1; 極限開關2 插 pinA1 

ezButton button1(2); //按鈕開關1 插 D2 
ezButton button2(3); //按鈕開關2 插 D3 
ezButton button3(4); //按鈕開關3 插 D4 
const byte speed = 220; //速度設定 0~255 
const byte ENB = 11; //設定輸出pwm 的腳位 
const byte INA3 =10; 
const byte INA4 =9; 
int tmp; 

//初始化區 
void setup() { 
 Serial.begin(9600);//使用 序列埠監控視窗 傳輸速度9600 

 limitSwitch_1.setDebounceTime(50); // 開關1 反應緩衝時間 50ms 
 limitSwitch_2.setDebounceTime(50); // 開關2 反應緩衝時間 50ms 
 button1.setDebounceTime(50);// 按鈕1 反應緩衝時間 50ms 
 button2.setDebounceTime(50);// 按鈕2 反應緩衝時間 50ms 
 button3.setDebounceTime(50);// 按鈕3 反應緩衝時間 50ms 

 pinMode(INA3,OUTPUT); 
 pinMode(INA4,OUTPUT); 
 } 
 //-------------------------------------- 

 //主程式區 

void loop() { 
 limitSwitch_1.loop(); // 呼叫極限開關1 迴圈函數 
 limitSwitch_2.loop(); // 呼叫極限開關2 迴圈函數 
 button1.loop();// 呼叫按鈕開關1 迴圈函數 
 button2.loop();// 呼叫按鈕開關2 迴圈函數 
 button3.loop();// 呼叫按鈕開關3 迴圈函數 

 int sensorValue2 = analogRead(A3); //取得A3 的風速數值 
 float outvoltage = sensorValue2 * (5.0 / 1023.0); 
 float speed = 6*outvoltage;// 風速等級和輸出電壓值呈線性關係 
 if (button2.isPressed()) { 
 Serial.println(F("Button2 is pressed.")); 
 }//條件句:若按鈕2 被壓則正轉(收回) 
 if (button3.isPressed()){ 
 tmp=1-tmp; 
 Serial.println(tmp); 
 }//條件句:按鈕開關被按1 次tmp=1 再壓一次為tmp=0 

 if (button3.isPressed()&&tmp==1) { 
 dcMStop(); //停止 
 Serial.println(F("Button3 is pressed.")); 
 } //條件句:若壓按鈕3 且tmp 為1 則停止 
 if (limitSwitch_1.isPressed()||limitSwitch_2.isPressed()) { 
 dcMStop(); //停止 
 Serial.println(F("The limit switch: TOUCHED")); 
 } //條件句:若極限開關1 或極限開關2 壓住則停止 
 if (button1.isPressed()&&limitSwitch_2.isReleased()) { 
 dcMRE(); //反轉(外推) 
 tmp=0; 
 Serial.println(F("Button1 is pressed.")); 
 } //條件句:若按鈕1 被壓則反轉(外推) 
 if (button2.isPressed()&&limitSwitch_1.isReleased()) { 
 tmp=0; 
 dcMFO(); //正轉 
 Serial.println(F("Button2 is pressed.")); 
 }//條件句:若按鈕2 被壓則正轉(收回) 

 if (speed>7&&limitSwitch_1.isReleased()) { 
 tmp=0; 
 dcMFO(); //正轉 
 Serial.println(F("Button2 is pressed.")); 
 }//條件句:若按鈕2 被壓則正轉(收回) 
} 
//自定義函式區 
//==================================== 
//馬達停止 
void dcMStop(){ 
analogWrite(ENB,0); 
} 
//==================================== 
//馬達啟動-正轉 
void dcMFO(){ 
analogWrite(ENB,speed); 
digitalWrite(INA3,HIGH); 
digitalWrite(INA4,LOW); 
} 
//==================================== 
//馬達啟動-反轉 
void dcMRE(){ 
analogWrite(ENB,speed); 
digitalWrite(INA3,LOW); 
digitalWrite(INA4,HIGH); 
} 

(2) 導風葉片開合機構控制Arduino 程式碼 
#include <Servo.h> 
#include <LiquidCrystal_I2C.h> 
// Set the LCD address to 0x27 for a 16 chars and 2 line display 
LiquidCrystal_I2C lcd(0x27, 16, 2); 
Servo myservo1; // create servo object to control the servo1 
Servo myservo2; // create servo object to control the servo2 
int val1; // variable to read the value from the analog pin9 
int val2; // variable to read the value from the analog pin10 
int x1; 
int x2; 

// 設定平均值讀取數 
const int numReadings = 10; 
// 定義儲存讀入數值的陣列變數 
int readings[numReadings]; 
// 定義指示陣列索引參數 
int readIndex = 0; 
// 定義儲存數總和 
int total = 0; 
// 定義儲存數的平均数 
int average = 0; 
void setup() { 
 Serial.begin(9600);// 
 myservo1.attach(9); // attaches the servo1 on pin 9 
 myservo2.attach(10); // attaches the servo2 on pin 10 
 // initialize the LCD, 
 lcd.begin(); 
 // Turn on the blacklight and print a message. 
 lcd.backlight(); 
 // 初始化每一數值的陣列為0， 
 for (int thisReading = 0; thisReading < numReadings; thisReading++) { 
 readings[thisReading] = 0; 
 } 
} 
void loop() { 
 // read the input on analog pin A2 A3: 
 int sensorValue1 = analogRead(A2); //取得A2 的數值 
 int sensorValue2 = analogRead(A3); //取得A3 的數值 
 float voltage = (sensorValue1*5.0)/1023.0; 
 float outvoltage = sensorValue2 * (5.0 / 1023.0); 
 float speed = 6*outvoltage;//風速和輸出電壓值呈線性關係 
// 平均值濾波運算 
 total = total - readings[readIndex]; 
 readings[readIndex] = map(sensorValue1, 0, 1023, 0, 360); 
 total = total + readings[readIndex]; 
 readIndex = readIndex + 1; 
 if (readIndex >= numReadings) { 
 readIndex = 0; 
 } 

 average = total / numReadings; 
 Serial.println(average); 
 int direction=average; 
 //設定伺服馬達開合控制 
 if(direction<220&&direction>130){ 
 val1=11; 
 val2=11; }//左開右關 
 else if (direction<130&&direction>50){ 
 val1=11; 
 val2=75; }//雙開 
 else if(direction<50){ 
 val1=75; 
 val2=75; }//左關右開 
 else{ 
 val1=11; 
 val2=75; }//雙開 
 if(x1==val1 && x2==val2){ 
 Serial.print("same"); 
 } 
 else { 
 myservo1.write(val1); 
 myservo2.write(val2); 
 x1=val1; 
 x2=val2;} 
 //LCD1602 顯示內容設定 
 lcd.clear();// clearn previous values from screen 
 lcdDisplay(0, // character 0 
 0, // line 0 
 "Direction", 
 10, // character 11 
 0, // line 0 
 direction, 
 13, // character 13 
 1, // line 1 
 "°" 
 ); 
 lcdDisplay(0, // character 0 
 1, // line 1 

 "Windspeed", 
 10, // character 11 
 1, // line 1 
 speed , 
 13, // character 14 
 1, // line 1 
 "m/s" 
 ); 
 delay(500); } 
void lcdDisplay(int tc, int tr, String title, int vc, int vr, float value,int wc, int wr, 
String units)//自訂lcd 函數定義參數 
{ 
 lcd.setCursor (tc,tr); // 
 lcd.print(title); 
 lcd.setCursor (vc,vr); // 
 lcd.print(value); 
 lcd.setCursor (wc,wr); // 
 lcd.print(units); } 

